def curate(filename):
 path=ROOT/'data/questions/drafts'/filename;bank=json.loads(path.read_text(encoding='utf-8'));changed=[]
 for q in bank['questions']:
  if q['id'] not in WRONG:continue
  correct=q['correct_answer'] if isinstance(q['correct_answer'],list) else [q['correct_answer']]
  right=[o['text'] for o in q['options'] if o['id'] in correct];wrong=WRONG[q['id']]
  if q['id']=='p1-d01-x15':right=['Quality','Latency','Cost']
  assert len(right)+len(wrong)>=3
  tagged=[(s,True) for s in right]+[(s,False) for s in wrong];shift=int(q['id'][-2:])%len(tagged);tagged=tagged[shift:]+tagged[:shift];q['options']=[{'id':chr(97+i),'text':s} for i,(s,_) in enumerate(tagged)];answers=[chr(97+i) for i,(_,ok) in enumerate(tagged) if ok];q['correct_answer']=answers if q['answer_format']=='multiple_choice' else answers[0];q['revision']+=1;changed.append(q['id'])
  q['review_notes'].append('Distractors explicitly revised to neighboring misconceptions in the same concept; three options avoid unrelated filler.')
 validator=Draft202012Validator(json.loads((ROOT/'docs/schemas/question-bank.schema.json').read_text(encoding='utf-8')));validator.validate(bank);path.write_text(json.dumps(bank,ensure_ascii=False,indent=2),encoding='utf-8');print(filename,len(changed),'revised')
if __name__=='__main__':
 import sys
 for name in sys.argv[1:] or ['expand-a-001.json']:curate(name)
